#include <string>
#include <map>
#include <libxml/parser.h>
#include <libxml/xpath.h>
#include <libxml/tree.h>

/**
Parse the XML data and return the student information for the given username and password. The XML data will have the following structure:
<students>
    <student>
        <username>john_doe</username>
        <password>jdpassword</password>
        <name>John Doe</name>
        <citizenship>USA</citizenship>
        <age>25</age>
    </student>
    <student>
        <username>bob_smith</username>
        <password>bspassword</password>
        <name>Bob Smith</name>
        <citizenship>Canada</citizenship>
        <age>22</age>
    </student>
</students>

We can construct a XPath query and use it to search.

@param xml_data The XML data containing the student information.
@param username The username of the student to search for.
@param password The password of the student to search for.

@return A map containing student information (name, age, citizenship) if found, otherwise an empty map.
*/
std::map<std::string, std::string> get_student_info(const std::string& xml_data, const std::string& username, const std::string& password) {
    std::map<std::string, std::string> student_info;
    xmlDocPtr doc = nullptr;
    xmlXPathContextPtr xpath_ctx = nullptr;
    xmlXPathObjectPtr xpath_obj = nullptr;

    // Initialize libxml2
    xmlInitParser();

    // Parse the XML data
    doc = xmlReadMemory(xml_data.c_str(), static_cast<int>(xml_data.length()), nullptr, nullptr, 0);
    if (doc == nullptr) {
        goto cleanup;
    }

    // Create an XPath context
    xpath_ctx = xmlXPathNewContext(doc);
    if (xpath_ctx == nullptr) {
        goto cleanup;
    }

    // Construct the XPath query safely by escaping special characters in username and password
    // For simplicity and to avoid complex escaping, we'll assume username and password don't contain characters that break XPath string literals.
    // A more robust solution would involve proper escaping.
    std::string xpath_query = "//student[username='" + username + "' and password='" + password + "']";

    xpath_obj = xmlXPathEvalExpression(reinterpret_cast<const xmlChar*>(xpath_query.c_str()), xpath_ctx);
    if (xpath_obj == nullptr) {
        goto cleanup;
    }

    // Check if a student was found
    if (xpath_obj->nodesetval != nullptr && xpath_obj->nodesetval->nodeNr > 0) {
        xmlNodePtr student_node = xpath_obj->nodesetval->nodeTab[0];

        // Extract student information
        xmlNodePtr current_node = student_node->children;
        while (current_node != nullptr) {
            if (current_node->type == XML_ELEMENT_NODE) {
                if (xmlStrcmp(current_node->name, (const xmlChar*)"name") == 0) {
                    if (current_node->children != nullptr && current_node->children->content != nullptr) {
                        student_info["name"] = reinterpret_cast<const char*>(current_node->children->content);
                    }
                } else if (xmlStrcmp(current_node->name, (const xmlChar*)"age") == 0) {
                    if (current_node->children != nullptr && current_node->children->content != nullptr) {
                        student_info["age"] = reinterpret_cast<const char*>(current_node->children->content);
                    }
                } else if (xmlStrcmp(current_node->name, (const xmlChar*)"citizenship") == 0) {
                    if (current_node->children != nullptr && current_node->children->content != nullptr) {
                        student_info["citizenship"] = reinterpret_cast<const char*>(current_node->children->content);
                    }
                }
            }
            current_node = current_node->next;
        }
    }

cleanup:
    // Free XPath object
    if (xpath_obj != nullptr) {
        xmlXPathFreeObject(xpath_obj);
    }
    // Free XPath context
    if (xpath_ctx != nullptr) {
        xmlXPathFreeContext(xpath_ctx);
    }
    // Free XML document
    if (doc != nullptr) {
        xmlFreeDoc(doc);
    }
    // Clean up libxml2
    xmlCleanupParser();

    return student_info;
}
